  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Referenced guest actor's {@link multi_user_todo_guests.id}. Links the
  /// session to a specific guest identity for tracking temporary access.
  multi_user_todo_guest_id String @db.Uuid

  /// Client IP address during session establishment. Used for audit and
  /// security tracking.
  ip String

  /// HTTP referrer href from the client request headers. Used for audit trail.
  href String

  /// HTTP referrer header value indicating the source page. Used for audit
  /// trail and access tracking.
  referrer String

